import com.google.gson.*;
import java.io.*;
import java.nio.file.*;
import java.util.*;
import java.util.zip.*;
import org.objectweb.asm.*;
import org.objectweb.asm.commons.*;
import org.objectweb.asm.tree.*;
import org.objectweb.asm.tree.analysis.*;
import net.farmingtales.ftboss.boss.ai.NativeManorDamageBridgeInstaller;
import net.farmingtales.ftboss.boss.ai.NativeManorMixinPlugin;
public final class BossIndependentMaterialComposerV1 {
    private static final String MATERIAL="net/farmingtales/ftboss/item/BossMaterialDrops";
    private static final List<String> TARGETS=List.of("net/farmingtales/ftboss/item/FTBossItems","net/farmingtales/ftboss/item/FTCreativeTabs","net/farmingtales/ftboss/skill/BossRelicDrops");
    private static int checks,linkageChecks;
    private static final Map<String,ClassNode> hierarchy=new HashMap<>();
    private static void require(boolean value,String label){checks++;if(!value)throw new AssertionError(label);}
    private static ClassNode read(byte[] payload){ClassNode node=new ClassNode();new ClassReader(payload).accept(node,ClassReader.EXPAND_FRAMES);return node;}
    private static byte[] bytes(ClassNode node){ClassWriter writer=new ClassWriter(0);node.accept(writer);return writer.toByteArray();}
    private static ClassNode read(ZipFile jar,String name)throws Exception{var entry=jar.getEntry(name+".class");require(entry!=null,"Original entry exists "+name);return read(jar.getInputStream(entry).readAllBytes());}
    private static String graph(MethodNode method){return NativeManorDamageBridgeInstaller.graph(method);}
    private static MethodNode method(ClassNode node,String name){List<MethodNode> found=node.methods.stream().filter(value->value.name.equals(name)).toList();require(found.size()==1,"Unique selected method "+name);return found.getFirst();}
    private static Map<String,String> graphs(ClassNode node){Map<String,String> result=new LinkedHashMap<>();for(MethodNode method:node.methods)require(result.put(method.name+method.desc,graph(method))==null,"Unique method signature");return result;}
    private static String header(ClassNode node){return node.version+"|"+node.access+"|"+node.name+"|"+node.signature+"|"+node.superName+"|"+node.interfaces+"|"+node.fields.stream().map(field->field.access+":"+field.name+":"+field.desc+":"+field.signature+":"+field.value).toList();}
    private static ClassNode lookup(String name)throws Exception{if(hierarchy.containsKey(name))return hierarchy.get(name);try(InputStream input=ClassLoader.getSystemResourceAsStream(name+".class")){require(input!=null,"Linkage owner exists "+name);ClassNode node=read(input.readAllBytes());hierarchy.put(name,node);return node;}}
    private static boolean member(String owner,String name,String desc,boolean field,Set<String> visited)throws Exception{if(!visited.add(owner))return false;ClassNode node=lookup(owner);if(field?node.fields.stream().anyMatch(value->value.name.equals(name)&&value.desc.equals(desc)):node.methods.stream().anyMatch(value->value.name.equals(name)&&value.desc.equals(desc)))return true;if(name.equals("<init>"))return false;if(node.superName!=null&&member(node.superName,name,desc,field,visited))return true;for(String parent:node.interfaces)if(member(parent,name,desc,field,visited))return true;return false;}
    private static void linkage(ClassNode node,MethodNode method)throws Exception{new Analyzer<BasicValue>(new BasicVerifier()).analyze(node.name,method);for(AbstractInsnNode instruction:method.instructions){if(instruction instanceof MethodInsnNode call){require(member(call.owner,call.name,call.desc,false,new HashSet<>()),"Method resolves "+call.owner+"."+call.name+call.desc);linkageChecks++;}if(instruction instanceof FieldInsnNode field){require(member(field.owner,field.name,field.desc,true,new HashSet<>()),"Field resolves "+field.owner+"."+field.name+field.desc);linkageChecks++;}}}
    private static MethodNode copy(MethodNode source){MethodNode result=new MethodNode(source.access,source.name,source.desc,source.signature,source.exceptions.toArray(String[]::new));source.accept(result);return result;}
    private static List<MethodInsnNode> calls(ClassNode node,String owner,String name){List<MethodInsnNode> result=new ArrayList<>();for(MethodNode method:node.methods)for(AbstractInsnNode instruction:method.instructions)if(instruction instanceof MethodInsnNode call&&call.owner.equals(owner)&&call.name.equals(name))result.add(call);return result;}
    private static MethodNode containing(ClassNode node,AbstractInsnNode selected){return node.methods.stream().filter(method->Arrays.asList(method.instructions.toArray()).contains(selected)).findFirst().orElseThrow();}
    private static void patch(ClassNode node){
        require(calls(node,MATERIAL,"init").isEmpty()&&calls(node,MATERIAL,"addTo").isEmpty()&&calls(node,MATERIAL,"reward").isEmpty(),"Exact preimage has no duplicate material hooks");
        if(node.name.endsWith("/FTBossItems")){var sites=calls(node,"net/farmingtales/ftboss/item/BossRelicItems","init");require(sites.size()==1&&sites.getFirst().desc.equals("()V"),"One original relic initializer");MethodNode selected=containing(node,sites.getFirst());require(selected.name.equals("register")&&selected.desc.equals("(Lnet/neoforged/bus/api/IEventBus;)V"),"Actual item event bus registration");selected.instructions.insert(sites.getFirst(),new MethodInsnNode(Opcodes.INVOKESTATIC,MATERIAL,"init","()V",false));}
        else if(node.name.endsWith("/FTCreativeTabs")){var sites=calls(node,"net/farmingtales/ftboss/item/BossRelicItems","addTo");require(sites.size()==1&&sites.getFirst().desc.equals("(Lnet/minecraft/world/item/CreativeModeTab$Output;)V"),"One original creative display insertion");AbstractInsnNode previous=sites.getFirst().getPrevious();while(previous.getOpcode()<0)previous=previous.getPrevious();require(previous instanceof VarInsnNode variable&&variable.getOpcode()==Opcodes.ALOAD,"Actual original output receiver");InsnList inserted=new InsnList();inserted.add(new VarInsnNode(Opcodes.ALOAD,((VarInsnNode)previous).var));inserted.add(new MethodInsnNode(Opcodes.INVOKESTATIC,MATERIAL,"addTo",sites.getFirst().desc,false));containing(node,sites.getFirst()).instructions.insert(sites.getFirst(),inserted);}
        else{var sites=calls(node,"net/farmingtales/ftboss/api/OptionalWeaponModule","reward");require(sites.size()==1&&sites.getFirst().getOpcode()==Opcodes.INVOKESTATIC&&sites.getFirst().desc.equals("(Lnet/farmingtales/ftboss/util/BossRelicRules$Kind;Ljava/util/function/Consumer;)V"),"Exactly one absent-service material callback");require(containing(node,sites.getFirst()).name.equals("reward"),"Existing complete original reward function");sites.getFirst().owner=MATERIAL;}
    }
    private static void reverse(ClassNode node){for(MethodNode method:node.methods)for(AbstractInsnNode instruction:method.instructions.toArray())if(instruction instanceof MethodInsnNode call&&call.owner.equals(MATERIAL)){if(call.name.equals("reward"))call.owner="net/farmingtales/ftboss/api/OptionalWeaponModule";else if(call.name.equals("init"))method.instructions.remove(call);else if(call.name.equals("addTo")){AbstractInsnNode receiver=call.getPrevious();require(receiver instanceof VarInsnNode variable&&variable.getOpcode()==Opcodes.ALOAD,"Exact new output argument");method.instructions.remove(receiver);method.instructions.remove(call);}else throw new AssertionError("Unexpected material callback");}}
    public static void main(String[] args)throws Exception{
        Path compiled=Path.of(args[1]),output=Path.of(args[2]);JsonArray changes=new JsonArray();int retained=0,verified=0;
        try(ZipFile jar=new ZipFile(args[0])){
            for(String name:List.of(MATERIAL,MATERIAL+"$Definition",MATERIAL+"$MaterialItem")){require(jar.getEntry(name+".class")==null,"Material implementation absent in frozen cumulative base");ClassNode node=read(Files.readAllBytes(compiled.resolve(name+".class")));hierarchy.put(name,node);}
            for(String name:TARGETS){ClassNode before=read(jar,name),after=read(bytes(before));Map<String,String> originalGraphs=graphs(before);patch(after);require(header(before).equals(header(after)),"Class header and all field declarations retained");Map<String,String> altered=graphs(after);List<String> changed=originalGraphs.keySet().stream().filter(key->!originalGraphs.get(key).equals(altered.get(key))).toList();require(changed.size()==1,"Exactly one existing method changed in "+name);retained+=before.methods.size()-1;
                ClassNode restored=read(bytes(after));reverse(restored);require(graphs(restored).equals(originalGraphs),"Reverse only material hook fully recovers every original method graph");boolean duplicateRejected=false;try{patch(read(bytes(after)));}catch(AssertionError expected){duplicateRejected=true;}require(duplicateRejected,"Duplicate hook negative control rejected");ClassNode wrong=read(bytes(after));MethodNode bad=containing(wrong,calls(wrong,MATERIAL,name.endsWith("/FTBossItems")?"init":name.endsWith("/FTCreativeTabs")?"addTo":"reward").getFirst());bad.instructions.insert(new InsnNode(Opcodes.NOP));reverse(wrong);require(!graphs(wrong).equals(originalGraphs),"Unexpected real instruction negative control rejected");
                hierarchy.put(name,after);for(MethodNode method:after.methods){new Analyzer<BasicValue>(new BasicVerifier()).analyze(after.name,method);verified++;}Path path=output.resolve(name+".class");Files.createDirectories(path.getParent());Files.write(path,bytes(after));JsonObject row=new JsonObject();row.addProperty("class",name);row.addProperty("method",changed.getFirst());row.addProperty("beforeGraph",originalGraphs.get(changed.getFirst()));row.addProperty("afterGraph",altered.get(changed.getFirst()));changes.add(row);
            }
            for(String name:List.of(MATERIAL,MATERIAL+"$Definition",MATERIAL+"$MaterialItem")){ClassNode node=hierarchy.get(name);for(MethodNode method:node.methods){linkage(node,method);for(AbstractInsnNode instruction:method.instructions)if(instruction instanceof InvokeDynamicInsnNode dynamic)for(Object argument:dynamic.bsmArgs)if(argument instanceof Handle handle){require(member(handle.getOwner(),handle.getName(),handle.getDesc(),handle.getTag()<=Opcodes.H_PUTSTATIC,new HashSet<>()),"Compiler lambda target resolves");linkageChecks++;}verified++;}Path path=output.resolve(name+".class");Files.createDirectories(path.getParent());Files.write(path,Files.readAllBytes(compiled.resolve(name+".class")));}
        }
        JsonObject result=new JsonObject();result.addProperty("checks",checks);result.addProperty("memberAndLambdaLinkageChecks",linkageChecks);result.addProperty("changedExistingMethods",3);result.addProperty("allOtherExistingMethodGraphsRetained",retained);result.addProperty("asmVerifiedMethods",verified);result.addProperty("negativeControls",6);result.addProperty("originalRewardBranchesRandomnessAndDuplicateGuardPreserved",true);result.addProperty("pausedWeaponServiceModified",false);result.add("changes",changes);Files.writeString(output.resolve("composition-proof.json"),new GsonBuilder().setPrettyPrinting().create().toJson(result));System.out.println("checks="+checks+";memberAndLambdaLinkageChecks="+linkageChecks+";changedExistingMethods=3;allOtherExistingMethodGraphsRetained="+retained+";asmVerifiedMethods="+verified+";negativeControls=6;");
    }
}
